var n=`1373-pisca-andina`;var t=`world-1373`;var a=`VE`;var o=`south-america`;var s=4;var r=49;var g={en:`Pisca Andina`,ua:`Піска андіна`};var m={en:`Pisca Andina is a dish from Venezuela featuring yellow onion, garlic, potato, cilantro. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Піска андіна, страва кухні країни Венесуела з такими основними складниками: жовта цибуля, часник, картопля, кінза. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`unsalted-butter`,45,`g`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 28 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 28 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:28,i:[[`potato`,560,`g`],[`chicken-stock`,1e3,`ml`],[`cilantro`,25,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 9 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 9 хвилин до готовності й м’якості.`,t:[`poaching`],m:9,i:[[`chicken-egg`,4,`pcs`],[`whole-cow-milk`,280,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,25,`g`]]}];var d={slug:n,id:t,country:`VE`,region:o,servings:4,minutes:49,title:g,text:m,steps:l};export{a as country,d as default,t as id,r as minutes,o as region,s as servings,n as slug,l as steps,m as text,g as title};